#pragma once

// Guarded private data sink for the downed groan / breath lines (the ext's
// vox_downed.h: VXD_LINES / VXD_RANGE / VXD_N, generated by
// tools/features/vox_lines.py gendowned). The take SIDs are game-derived and
// do not ship here, so every read lives behind TO1_DOWNED_VOX_DATA.
//
// Build with -DTO1_DOWNED_VOX_DATA and supply a private
// net/audio/downed_vox_data.hpp declaring these UNQUALIFIED names. That header
// is included below from inside the already-open
// net::audio::downed_vox::data namespace, so it must NOT wrap them in another
// namespace:
//   extern const uint64_t kLines[];                    // VXD_LINES: at least kCount entries
//   inline constexpr int kRange[2][2][4][3][2] = { ... };  // VXD_RANGE
//   inline constexpr int kCount = ...;                 // VXD_N: number of kLines entries
//
// kRange is indexed [fac][female][voice][kind][field]: fac 0 = Seraphite,
// 1 = WLF; female 0/1; voice 0..3 (the body's a..d voice bank); kind 0 = groan
// (lying), 1 = breath (crawling); field 0 = first index into kLines, field 1 =
// count of consecutive takes (<= 0 means "no take of this kind"). The pure
// core never indexes kind 2, so the ext's one-past-the-end headshot read is not
// reproduced. A generator shim over VXD_LINES / VXD_RANGE / VXD_N works as-is;
// a definition of kLines in a .cpp is fine as long as the extern declaration is
// visible here.
//
// With the macro off, kHave is false and Table() returns an empty core::LineTable:
// the owner then starts no groan/breath voice, asks no is-speaking?, draws no
// RNG value and stamps no cadence. Headshot gargles are engine voice names and
// stay live either way. The ext has no separate opt-out for the private table
// itself; its sidecars are handled in the owner.

#include "downed-vox-core.hpp"

namespace net::audio::downed_vox::data {

#if defined(TO1_DOWNED_VOX_DATA)
#  include "downed_vox_data.hpp"

    inline constexpr bool kHave = true;

    inline core::LineTable Table() noexcept { return { kLines, kRange, kCount }; }

    inline uint64_t Line(int index) noexcept
    {
        return index >= 0 && index < kCount ? kLines[index] : 0;
    }

#else

    inline constexpr bool kHave = false;
    inline constexpr int kCount = 0;

    inline core::LineTable Table() noexcept { return {}; }

    inline uint64_t Line(int) noexcept { return 0; }

#endif

} // namespace net::audio::downed_vox::data
